import random
import struct
from typing import List

# Generator for an arbitrary binary string that is interesting for
# dealii::Utilities::compress (zlib-enabled builds) and safe as raw bytes.
# Goals:
# - Produce buffers under 2048 bytes (fuzzer truncates beyond that)
# - Cover a variety of compressibility patterns:
#   * Highly compressible (repetitive)
#   * Moderately compressible (structured, patterned)
#   * Poorly compressible (high entropy)
#   * Small edge cases (empty, tiny sizes)
#   * Mixed segments including zeros, ASCII text, random, repeated runs
# - Deterministic w.r.t. provided seed, yet varied across calls.

MAX_SIZE = 2048

def _rand(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))

def _repeated_byte(r: random.Random, length: int) -> bytes:
    b = r.randrange(256)
    return bytes([b]) * length

def _repeated_pattern(r: random.Random, pattern_len: int, total_len: int) -> bytes:
    patt = bytes(r.getrandbits(8) for _ in range(pattern_len))
    return (patt * (total_len // len(patt) + 1))[:total_len]

def _ascii_text_block(r: random.Random, length: int) -> bytes:
    # Mix of printable ASCII and whitespace, with some common words
    words = [
        b"deal.II ", b"version ", b"utilities ", b"compress ", b"point ", b"tensor ",
        b"decompress ", b"base64 ", b"random ", b"system ", b"memory ", b"stats ",
    ]
    buf = bytearray()
    while len(buf) < length:
        if r.random() < 0.5:
            w = r.choice(words)
            buf.extend(w)
        else:
            c = r.randrange(32, 127)
            buf.append(c)
        if r.random() < 0.2:
            buf.append(10)  # newline
        if r.random() < 0.1:
            buf.append(9)   # tab
    return bytes(buf[:length])

def _structured_blocks(r: random.Random, target_len: int) -> bytes:
    # Build a sequence of segments with different characteristics
    if target_len <= 0:
        return b""
    segments: List[bytes] = []
    remaining = target_len
    while remaining > 0:
        choice = r.random()
        seg_len = min(remaining, r.randint(16, max(16, min(256, remaining))))
        if seg_len <= 0:
            break
        if choice < 0.20:
            segments.append(_repeated_byte(r, seg_len))
        elif choice < 0.40:
            patt_len = r.choice([2, 3, 4, 5, 7, 8, 16])
            segments.append(_repeated_pattern(r, patt_len, seg_len))
        elif choice < 0.60:
            segments.append(_ascii_text_block(r, seg_len))
        elif choice < 0.80:
            segments.append(_rand(r, seg_len))
        else:
            # Mixed: zeros then small pattern. Ensure randint has a valid range.
            if seg_len <= 4:
                zeros = seg_len
                rest = 0
            else:
                zeros = min(seg_len, r.randint(4, seg_len - 1))
                rest = seg_len - zeros
            segments.append(bytes(zeros))
            if rest > 0:
                segments.append(_repeated_pattern(r, r.choice([3, 4, 5, 6, 7, 8]), rest))
        remaining -= seg_len
    return b"".join(segments)

def _gzip_header_like(r: random.Random) -> bytes:
    # Not producing a full valid gzip stream, just a header-like prefix.
    hdr = bytearray([0x1f, 0x8b, 0x08, 0x00])
    hdr.extend(struct.pack("<I", r.getrandbits(32)))  # MTIME
    hdr.append(0x00)  # XFL
    hdr.append(r.randrange(256))  # OS
    return bytes(hdr)

def _zlib_header_like(r: random.Random) -> bytes:
    # A plausible zlib header (CMF/FLG); adjust FCHECK for mod-31.
    cmf = 0x78  # deflate + 32K window
    flg_base = r.randrange(0, 256) & 0xE0
    for fcheck in range(32):
        flg = flg_base | fcheck
        if ((cmf << 8) + flg) % 31 == 0:
            return bytes([cmf, flg])
    return bytes([cmf, 0x9C])

def _make_candidate(r: random.Random) -> bytes:
    profile = r.choice([
        "empty",
        "tiny",
        "zeros",
        "repeated_byte",
        "repeated_pattern",
        "ascii",
        "random",
        "structured",
        "gzip_like_prefix",
        "zlib_like_prefix",
        "mixed_prefix_structured",
    ])

    if profile == "empty":
        return b""
    if profile == "tiny":
        n = r.randint(1, 8)
        return _rand(r, n)
    if profile == "zeros":
        return bytes(r.randint(1, 1024))
    if profile == "repeated_byte":
        return _repeated_byte(r, r.randint(16, 1024))
    if profile == "repeated_pattern":
        plen = r.choice([2, 3, 4, 5, 7, 8, 16, 32])
        total = r.randint(32, 1536)
        return _repeated_pattern(r, plen, total)
    if profile == "ascii":
        return _ascii_text_block(r, r.randint(32, 1500))
    if profile == "random":
        return _rand(r, r.randint(16, 1536))
    if profile == "structured":
        return _structured_blocks(r, r.randint(64, 1800))
    if profile == "gzip_like_prefix":
        pref = _gzip_header_like(r)
        tail = _structured_blocks(r, r.randint(32, 512))
        return (pref + tail)[:MAX_SIZE]
    if profile == "zlib_like_prefix":
        pref = _zlib_header_like(r)
        tail = _structured_blocks(r, r.randint(32, 1024))
        return (pref + tail)[:MAX_SIZE]
    if profile == "mixed_prefix_structured":
        parts = []
        if r.random() < 0.5:
            parts.append(_gzip_header_like(r))
        if r.random() < 0.5:
            parts.append(_zlib_header_like(r))
        body_len = r.randint(64, 1500)
        parts.append(_structured_blocks(r, body_len))
        return b"".join(parts)[:MAX_SIZE]

    return _structured_blocks(r, r.randint(32, 1024))


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Occasionally choose a specific size near boundary to test truncation path
    if r.random() < 0.2:
        target = MAX_SIZE
    else:
        target = r.randint(0, MAX_SIZE)

    data = _make_candidate(r)

    # Adjust size toward target while preserving structure:
    if len(data) > target:
        data = data[:target]
    elif len(data) < target:
        need = target - len(data)
        if need > 0:
            if r.random() < 0.5 and len(data) > 0:
                # repeat tail
                base = data[-min(16, len(data)):] or b"\x00"
                chunk = (base * (need // max(1, len(base)) + 1))[:need]
                data = data + chunk
            else:
                data = data + _structured_blocks(r, need)

    return data[:MAX_SIZE]

import random
import string
from typing import List

# This generator targets dealii::Utilities::split_string_list fuzzers.
# The fuzzer requests two kinds of inputs via FUZZ_PARAM_STR (bounded to 256/8 chars)
# and a char delimiter via a single unsigned char. We provide a bytes blob that,
# when split by the harness, yields interesting valid strings for both overloads.
#
# Common corpus layout strategy (single buffer):
# - First section: primary string s for string-delimiter overload (<=256 bytes)
# - Second section: string delimiter d (1..8 bytes, non-empty)
# - Third section: primary string s2 for char-delimiter overload (<=256 bytes)
# - Fourth section: single byte char delimiter cd (0..255)
# Sections are encoded with tiny length prefixes to allow the harness to pick
# them deterministically from the single FUZZ input. While the harness is opaque,
# this organization makes the buffer self-descriptive and useful for re-use.
#
# Strings include diverse cases: empty fields, leading/trailing delimiters,
# multiple adjacent delimiters, quoted fields, Unicode, numbers, whitespace,
# newlines, tabs, punctuation, and unusual delimiter tokens.

MAX_S_LEN = 256
MAX_DELIM_LEN = 8
MAX_TOTAL = 4096


def _weighted_choice(rng: random.Random, items: List[str], weights: List[int]) -> str:
    total = sum(weights)
    pick = rng.randrange(total)
    acc = 0
    for item, w in zip(items, weights):
        acc += w
        if pick < acc:
            return item
    return items[-1]


def _rand_ascii(rng: random.Random, n: int) -> str:
    # Include spaces and punctuation to stress trimming and splitting
    alphabet = string.ascii_letters + string.digits + " \t\n\r_-+*/=:;,.|!@#$%^&()[]{}<>?\"'\\"
    return ''.join(rng.choice(alphabet) for _ in range(n))


def _gen_delim_string(rng: random.Random) -> str:
    # Curated interesting delimiters
    candidates = [
        ",", ";", " ", "\t", "|", ":", "::", "--", "==", "..", ":::", "\\t",
        " / ", " , ", "\n", "\r\n", "\t|\t", "###", "&&", "++"
    ]
    if rng.random() < 0.75:
        d = rng.choice(candidates)
    else:
        # Random length 1..8, avoid empty
        d = _rand_ascii(rng, rng.randint(1, MAX_DELIM_LEN))
    # Ensure non-empty and within 8 bytes once encoded
    enc = d.encode('utf-8')[:MAX_DELIM_LEN]
    if not enc:
        enc = b","  # fallback
    return enc.decode('utf-8', errors='ignore') or ","


def _gen_field(rng: random.Random) -> str:
    kinds = [
        "empty", "word", "number", "float", "spaces", "quoted", "unicode",
        "punct", "path", "email", "ip", "hex"
    ]
    k = rng.choice(kinds)
    if k == "empty":
        return ""
    if k == "word":
        return ''.join(rng.choice(string.ascii_letters) for _ in range(rng.randint(1, 12)))
    if k == "number":
        return str(rng.randint(-10**6, 10**6))
    if k == "float":
        return f"{rng.uniform(-1e6,1e6):.6f}"
    if k == "spaces":
        return " " * rng.randint(1, 6)
    if k == "quoted":
        inner = _rand_ascii(rng, rng.randint(0, 10))
        quote = rng.choice(['"', "'"])
        return f"{quote}{inner}{quote}"
    if k == "unicode":
        # Include some non-ascii code points
        cps = [0x00E9, 0x03B1, 0x0416, 0x20AC, 0x2603, 0x4E2D, 0x65E5]
        s = ''.join(chr(rng.choice(cps)) for _ in range(rng.randint(1, 6)))
        return s
    if k == "punct":
        return ''.join(rng.choice("-_.+/=:#@!?") for _ in range(rng.randint(1, 8)))
    if k == "path":
        parts = [
            ''.join(rng.choice(string.ascii_lowercase+string.digits) for _ in range(rng.randint(1,6)))
            for _ in range(rng.randint(1,4))
        ]
        prefix = "/" if rng.random() < 0.5 else ""
        return prefix + "/".join(parts)
    if k == "email":
        user = ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(1,6)))
        host = ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(3,8)))
        tld = rng.choice(["com","org","net","io","de","jp"])
        return f"{user}@{host}.{tld}"
    if k == "ip":
        return ".".join(str(rng.randint(0,255)) for _ in range(4))
    if k == "hex":
        return "0x" + ''.join(rng.choice('0123456789abcdef') for _ in range(rng.randint(1,8)))
    return "x"


def _assemble_s(rng: random.Random, delim: str, target_len: int) -> str:
    # Create a composite string with leading/trailing delimiters, adjacent delimiters,
    # embedded whitespace and newline splits to exercise trimming behavior.
    parts = []
    n_fields = rng.randint(3, 20)
    for _ in range(n_fields):
        f = _gen_field(rng)
        # Randomly add surrounding whitespace to test trimming
        if rng.random() < 0.6:
            left = ' ' * rng.randint(0, 2) + ('\t' if rng.random() < 0.2 else '')
            right = ('\t' if rng.random() < 0.2 else '') + ' ' * rng.randint(0, 2)
            f = left + f + right
        parts.append(f)
        # Occasionally insert empty fields by adding extra delimiter later
    s = delim.join(parts)

    # Spice: insert runs of delimiters to create empty components
    if rng.random() < 0.7 and len(delim) > 0:
        for _ in range(rng.randint(1, 3)):
            pos = rng.randint(0, len(s))
            s = s[:pos] + delim + s[pos:]

    # Add leading/trailing delimiters
    if rng.random() < 0.5:
        s = delim + s
    if rng.random() < 0.5:
        s = s + delim

    # Insert line breaks which should be treated as delimiters in width-breaking
    if rng.random() < 0.5:
        inserts = rng.randint(1, 3)
        for _ in range(inserts):
            pos = rng.randint(0, len(s))
            s = s[:pos] + ("\n" if rng.random() < 0.7 else "\r\n") + s[pos:]

    # Trim to target length in bytes, respecting UTF-8 encoding
    b = s.encode('utf-8')
    if len(b) > target_len:
        b = b[:target_len]
        # Avoid cutting inside multibyte sequence
        while b and (b[-1] & 0xC0) == 0x80:
            b = b[:-1]
        s = b.decode('utf-8', errors='ignore')
    return s


def _gen_char_delim(rng: random.Random) -> int:
    # Choose interesting single-character delimiters
    chars = [',', ';', ' ', '\t', '|', ':', '/', '\n', '\r', '.', '-', '+', '\0']
    if rng.random() < 0.8:
        c = rng.choice(chars)
        if c == '\0':
            return 0
        return ord(c)
    return rng.randrange(256)


def _pack_section(data: bytes) -> bytes:
    # 2-byte big-endian length prefix for section
    if len(data) > 65535:
        data = data[:65535]
    return len(data).to_bytes(2, 'big') + data


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide delimiters
    delim = _gen_delim_string(rng)

    # Build s for string-delimiter overload
    s = _assemble_s(rng, delim, MAX_S_LEN)

    # Possibly choose a different delimiter variant to create variety
    if rng.random() < 0.4:
        delim2 = _gen_delim_string(rng)
    else:
        delim2 = delim

    # Build s2 for char-delimiter overload using a chosen char delimiter
    cdel = _gen_char_delim(rng)
    cdel_chr = chr(cdel) if cdel != 0 else '\x00'

    # Choose a base composition for s2 that is aware of char delimiter
    # Ensure presence of delimiter, leading/trailing, and adjacent cases
    fields = [_gen_field(rng) for _ in range(rng.randint(4, 16))]
    s2 = cdel_chr.join(fields)
    if rng.random() < 0.7:
        s2 = cdel_chr + s2
    if rng.random() < 0.7:
        s2 = s2 + cdel_chr
    if rng.random() < 0.5:
        s2 = s2.replace(cdel_chr, cdel_chr * rng.randint(2, 4))

    # Insert whitespace around fields
    if rng.random() < 0.5:
        s2 = ' '.join(part if rng.random() < 0.5 else (' ' + part + ' ') for part in s2.split(cdel_chr))
        s2 = s2.replace('  ', ' ')
        s2 = s2.replace(' \t', '\t')

    # Enforce size bounds in bytes
    def clip_utf8(s: str, limit: int) -> str:
        b = s.encode('utf-8')
        if len(b) > limit:
            b = b[:limit]
            while b and (b[-1] & 0xC0) == 0x80:
                b = b[:-1]
            return b.decode('utf-8', errors='ignore')
        return s

    s = clip_utf8(s, MAX_S_LEN)
    delim2 = clip_utf8(delim2, MAX_DELIM_LEN)
    if not delim2:
        delim2 = ","
    s2 = clip_utf8(s2, MAX_S_LEN)

    # Pack into a single buffer with section lengths:
    # [len(s)][s][len(delim2)][delim2][len(s2)][s2][char_delim_byte]
    buf = bytearray()
    buf += _pack_section(s.encode('utf-8'))
    buf += _pack_section(delim2.encode('utf-8'))
    buf += _pack_section(s2.encode('utf-8'))
    buf.append(cdel & 0xFF)

    # Ensure total size limit
    if len(buf) > MAX_TOTAL:
        buf = buf[:MAX_TOTAL]

    return bytes(buf)

import random
import string
from typing import List

# This generator targets dealii::Utilities::split_string_list fuzzers.
# It should provide interesting valid buffers for FUZZ_PARAM_STR and a single-char delimiter.
# We will emit a bytes blob that concatenates:
# - A test string (<=256 bytes) possibly containing varied delimiters, whitespace, quotes, numbers, unicode-like bytes, and edge cases
# - A delimiter spec: either a chosen multi-char delimiter (<=8) for the string-delimiter overload
# - A single-byte delimiter for the char-delimiter overload
# The fuzzer framework will slice these as needed via FUZZ_PARAM_STR / FUZZ_PARAM(unsigned char),
# so we pack multiple candidate cases separated by newlines and markers to maximize utility.

def _rand_ws(r: random.Random) -> str:
    # include varied whitespace characters
    ws = [" ", "\t", "\n", "\r", "\v", "\f", "\u00A0", "\u2003"]
    return r.choice(ws)

def _rand_token(r: random.Random) -> str:
    kinds = ["alpha", "num", "alnum", "quoted", "empty", "symbols"]
    k = r.choice(kinds)
    if k == "alpha":
        ln = r.randint(1, 12)
        return ''.join(r.choice(string.ascii_letters) for _ in range(ln))
    if k == "num":
        # include signed and floating-point-like
        signs = ["", "+", "-"]
        sign = r.choice(signs)
        if r.random() < 0.5:
            return sign + str(r.randint(0, 10**6))
        else:
            return sign + str(r.randint(0, 9999)) + r.choice([".", ","]) + str(r.randint(0, 9999))
    if k == "alnum":
        ln = r.randint(1, 16)
        alphabet = string.ascii_letters + string.digits + "_-.:/"
        return ''.join(r.choice(alphabet) for _ in range(ln))
    if k == "quoted":
        inner_len = r.randint(0, 10)
        inner = ''.join(r.choice(string.ascii_letters + string.digits + " _-") for _ in range(inner_len))
        quote = r.choice(['"', "'"])
        return quote + inner + quote
    if k == "empty":
        return ""
    if k == "symbols":
        ln = r.randint(1, 6)
        return ''.join(r.choice("!@#$%^&*()[]{}<>|?~") for _ in range(ln))
    return "x"

def _rand_delim_str(r: random.Random) -> str:
    presets = [",", ";", " ", "|", "::", "->", "\t", ":::", "--", "|||", ": "]
    if r.random() < 0.6:
        return r.choice(presets)
    # random delimiter up to 8 bytes, avoid empty
    ln = r.randint(1, 8)
    pool = ",;|:\t-_/ "+string.punctuation
    # ensure not all whitespace sometimes
    d = ''.join(r.choice(pool) for _ in range(ln))
    return d

def _rand_char_delim(r: random.Random) -> bytes:
    # Single-byte delimiter. Include special/common and rare bytes.
    choices = [ord(c) for c in [',',';',' ', '\t','\n','|',':','-','/','\0']]
    if r.random() < 0.7:
        b = r.choice(choices)
    else:
        b = r.randrange(0, 256)
    return bytes([b])

def _build_case(r: random.Random) -> bytes:
    # Build a single case with a test string and delimiters.
    # We use a simple self-describing format to pack multiple cases:
    # [HEADER]\n
    # s=...\n
    # delim=...\n
    # ch=\xHH\n
    # data lines can include newlines; we escape them where helpful.

    # choose a delimiter string first to embed tokens accordingly
    dstr = _rand_delim_str(r)

    # create a list of tokens separated by varied combos of delimiter and whitespace
    num_tokens = r.randint(1, 20)
    tokens: List[str] = []
    for _ in range(num_tokens):
        tok = _rand_token(r)
        tokens.append(tok)

    # build separators: mix delimiter string with whitespace around
    parts: List[str] = []
    for i, t in enumerate(tokens):
        # optionally trim whitespace cases around tokens
        left_ws = ''.join(_rand_ws(r) for _ in range(r.randint(0, 2)))
        right_ws = ''.join(_rand_ws(r) for _ in range(r.randint(0, 2)))
        parts.append(left_ws + t + right_ws)
        if i != num_tokens - 1:
            # sometimes use delimiter, sometimes multiple delimiters in a row
            sep = dstr
            if r.random() < 0.2:
                sep = dstr * r.randint(2, 3)
            parts.append(sep)
    s = ''.join(parts)

    # Inject corner cases: leading/trailing delimiters, repeated delimiters, newlines
    if r.random() < 0.5:
        s = dstr + s
    if r.random() < 0.5:
        s = s + dstr
    if r.random() < 0.4:
        s = s.replace(dstr, dstr + _rand_ws(r))
    if r.random() < 0.3:
        # embed some explicit newlines which split_string_list treats as normal chars (except trimming around)
        for _ in range(r.randint(1, 3)):
            pos = r.randrange(0, len(s)+1)
            s = s[:pos] + "\n" + s[pos:]

    # Cap to 256 UTF-8 bytes when encoded; trim safely
    encoded = s.encode('utf-8', errors='ignore')
    if len(encoded) > 256:
        encoded = encoded[:256]
        try:
            s = encoded.decode('utf-8', errors='ignore')
        except Exception:
            s = encoded.decode('utf-8', errors='ignore')
            encoded = s.encode('utf-8', errors='ignore')

    # delimiter string cap 8 bytes
    dbytes = dstr.encode('utf-8', errors='ignore')[:8]
    # ensure not empty per fuzzer default fallback; but we allow empty here and rely on fuzzer to replace, still keep non-empty mostly
    if len(dbytes) == 0:
        dbytes = b","  # safe default

    # single-char delimiter
    ch = _rand_char_delim(r)

    # Assemble with simple markers; consumers are fuzzers not this script, markers just help pack multiple cases
    # Avoid NUL in text lines except ch which may contain NUL.
    out = bytearray()
    out += b"CASE\n"
    out += b"s=" + encoded.replace(b"\n", b"\\n") + b"\n"
    out += b"delim=" + dbytes.replace(b"\n", b"\\n") + b"\n"
    out += b"ch=" + ch.hex().encode('ascii') + b"\n"
    return bytes(out)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    cases = r.randint(3, 8)
    blob = bytearray()
    for _ in range(cases):
        blob += _build_case(r)
    # Ensure size limit
    if len(blob) > 4096:
        blob = blob[:4096]
    return bytes(blob)
